create or replace function public.get_current_user_product_entitlements() returns table(service_tier text,location_limit integer,enterprise_fleet_enabled boolean,fleet_enabled boolean) language sql security definer set search_path=public as $$ with derived as (select case when b.business_tier='growth' then 'enterprise' when b.business_tier='enterprise' then 'enterprise' when b.business_tier='fleet' then 'fleet' end::text as service_tier,case when b.business_tier='growth' then 5 else null end::integer as location_limit,case when b.business_tier='enterprise' then false else false end as enterprise_fleet_enabled,case when b.business_tier='fleet' then true else false end as fleet_enabled from public.businesses b join public.app_business_memberships m on m.business_id=b.id where m.user_id=auth.uid()), explicit as (select service_tier,location_limit,enterprise_fleet_enabled,fleet_enabled from public.account_service_entitlements where account_user_id=auth.uid()) select service_tier,location_limit,enterprise_fleet_enabled,fleet_enabled from derived where service_tier is not null union all select e.service_tier,e.location_limit,e.enterprise_fleet_enabled,e.fleet_enabled from explicit e where not exists(select 1 from derived d where d.service_tier=e.service_tier); $$;
